namespace {
std::string Trim(std::string value){auto white=[](unsigned char c){return std::isspace(c)!=0;};value.erase(value.begin(),std::find_if_not(value.begin(),value.end(),white));value.erase(std::find_if_not(value.rbegin(),value.rend(),white).base(),value.end());return value;}
std::string Number(auto value){char text[64]{};if constexpr(std::is_floating_point_v<decltype(value)>)sprintf_s(text,"%.9g",static_cast<double>(value));else sprintf_s(text,"%lld",static_cast<long long>(value));return text;}
}

namespace ProfileInternal {
STRINGBLOCK* STRINGBLOCK::AllocBlock(unsigned size){auto* block=new STRINGBLOCK;block->m_dataSize=size;return block;}
char* STRINGBLOCK::AllocString(std::vector<STRINGBLOCK*>&,const char* string,int){if(!string)return nullptr;const size_t size=std::strlen(string)+1;char* copy=new char[size];std::memcpy(copy,string,size);return copy;}
void STRINGBLOCK::FreeString(std::vector<STRINGBLOCK*>&,char* string){delete[] string;}
KEYVALUE* GetKeyValue(PROFILE* profile,const char* section,const char* key){if(!profile||!section||!key)return nullptr;auto sectionIt=profile->sectionTable.find(section);if(sectionIt==profile->sectionTable.end())return nullptr;auto keyIt=sectionIt->second.keyTable.find(key);return keyIt==sectionIt->second.keyTable.end()?nullptr:&keyIt->second;}
int ISetValue(PROFILE* profile,const char* section,const char* key,const char* value,int clear,int){if(!profile||!section||!key)return 0;KEYVALUE& target=profile->sectionTable[section].keyTable[key];if(clear)target.values.clear();if(value)target.values.emplace_back(value);return 1;}
void TokenizeStringValues(PROFILE* profile,const char* section,const char* key,char* value){if(!value)return;char* context=nullptr;for(char* token=strtok_s(value,",",&context);token;token=strtok_s(nullptr,",",&context))ISetValue(profile,section,key,Trim(token).c_str(),0);}
int IReadBuffer(PROFILE* profile,const void* data,unsigned bytes){if(!profile||(!data&&bytes))return 0;std::string input(static_cast<const char*>(data),bytes);std::istringstream stream(input);std::string line,section;while(std::getline(stream,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();line=Trim(line);if(line.empty()||line[0]==';'||line[0]=='#')continue;if(line.front()=='['&&line.back()==']'){section=Trim(line.substr(1,line.size()-2));profile->sectionTable.try_emplace(section);continue;}const size_t split=line.find('=');if(split==std::string::npos)continue;const std::string key=Trim(line.substr(0,split));std::string value=Trim(line.substr(split+1));ISetValue(profile,section.c_str(),key.c_str(),value.c_str(),0);}return 1;}
PROFILE* IReadFile(const char* path){PROFILE* profile=new PROFILE;if(!ProfileReadFile(profile,path)){delete profile;return nullptr;}return profile;}
void WriteLine(std::string& output,const char* format,...){char line[4096]{};va_list args;va_start(args,format);vsnprintf_s(line,sizeof(line),_TRUNCATE,format,args);va_end(args);output+=line;output+="\r\n";}
void WriteKey(std::string& output,const std::string& name,const KEYVALUE& key){for(const auto& value:key.values)WriteLine(output,"%s=%s",name.c_str(),value.c_str());}
void WriteSection(std::string& output,const std::string& name,const SECTION& section){WriteLine(output,"[%s]",name.c_str());std::vector<std::string> keys;for(const auto& [key,value]:section.keyTable)keys.push_back(key);std::sort(keys.begin(),keys.end());for(const auto& key:keys)WriteKey(output,key,section.keyTable.at(key));WriteLine(output,"");}
void WriteFileBuffer(PROFILE* profile,std::string& output){if(!profile)return;std::vector<std::string> sections;for(const auto& [name,value]:profile->sectionTable)sections.push_back(name);std::sort(sections.begin(),sections.end());for(const auto& name:sections)WriteSection(output,name,profile->sectionTable.at(name));}
int IWriteFile(PROFILE* profile,const char* path){if(!profile||!path)return 0;std::string output;WriteFileBuffer(profile,output);std::ofstream file(path,std::ios::binary|std::ios::trunc);file.write(output.data(),static_cast<std::streamsize>(output.size()));return file.good();}
const char* IGetValue(PROFILE* profile,const char* section,const char* key,unsigned index){KEYVALUE* value=GetKeyValue(profile,section,key);return value&&index<value->values.size()?value->values[index].c_str():nullptr;}
int PrfStrToInt(const char* value){return value?static_cast<int>(std::strtol(value,nullptr,0)):0;}
unsigned IGetNumValues(PROFILE* profile,const char* section,const char* key){KEYVALUE* value=GetKeyValue(profile,section,key);return value?static_cast<unsigned>(value->values.size()):0;}
}

HPROFILE ProfileCreate(){return new ProfileInternal::PROFILE;}
int ProfileReadFile(HPROFILE profile,const char* path){if(!profile||!path)return 0;std::ifstream file(path,std::ios::binary);if(!file)return 0;std::string contents((std::istreambuf_iterator<char>(file)),{});return ProfileInternal::IReadBuffer(profile,contents.data(),static_cast<unsigned>(contents.size()));}
int ProfileReadBuffer(HPROFILE profile,const void* data,unsigned bytes){return ProfileInternal::IReadBuffer(profile,data,bytes);}int ProfileWriteFile(HPROFILE profile,const char* path){return ProfileInternal::IWriteFile(profile,path);}
int ProfileAddValue(HPROFILE p,const char*s,const char*k,bool v){return ProfileInternal::ISetValue(p,s,k,v?"1":"0",0);}int ProfileAddValue(HPROFILE p,const char*s,const char*k,int v){return ProfileInternal::ISetValue(p,s,k,Number(v).c_str(),0);}int ProfileAddValue(HPROFILE p,const char*s,const char*k,std::int64_t v){return ProfileInternal::ISetValue(p,s,k,Number(v).c_str(),0);}int ProfileAddValue(HPROFILE p,const char*s,const char*k,float v){return ProfileInternal::ISetValue(p,s,k,Number(v).c_str(),0);}int ProfileAddValue(HPROFILE p,const char*s,const char*k,const unreal*v){return v?ProfileInternal::ISetValue(p,s,k,Number(*v).c_str(),0):0;}int ProfileAddValue(HPROFILE p,const char*s,const char*k,const char*v){return ProfileInternal::ISetValue(p,s,k,v,0);}
int ProfileSetValue(HPROFILE p,const char*s,const char*k,bool v){return ProfileInternal::ISetValue(p,s,k,v?"1":"0",1);}int ProfileSetValue(HPROFILE p,const char*s,const char*k,int v){return ProfileInternal::ISetValue(p,s,k,Number(v).c_str(),1);}int ProfileSetValue(HPROFILE p,const char*s,const char*k,std::int64_t v){return ProfileInternal::ISetValue(p,s,k,Number(v).c_str(),1);}int ProfileSetValue(HPROFILE p,const char*s,const char*k,float v){return ProfileInternal::ISetValue(p,s,k,Number(v).c_str(),1);}int ProfileSetValue(HPROFILE p,const char*s,const char*k,const unreal*v){return v?ProfileInternal::ISetValue(p,s,k,Number(*v).c_str(),1):0;}int ProfileSetValue(HPROFILE p,const char*s,const char*k,const char*v){return ProfileInternal::ISetValue(p,s,k,v,1);}
int ProfileGetValue(HPROFILE p,const char*s,const char*k,bool*v,unsigned i){const char*x=ProfileInternal::IGetValue(p,s,k,i);if(!x||!v)return 0;*v=ProfileInternal::PrfStrToInt(x)!=0;return 1;}int ProfileGetValue(HPROFILE p,const char*s,const char*k,int*v,unsigned i){const char*x=ProfileInternal::IGetValue(p,s,k,i);if(!x||!v)return 0;*v=ProfileInternal::PrfStrToInt(x);return 1;}int ProfileGetValue(HPROFILE p,const char*s,const char*k,std::int64_t*v,unsigned i){const char*x=ProfileInternal::IGetValue(p,s,k,i);if(!x||!v)return 0;*v=std::strtoll(x,nullptr,0);return 1;}int ProfileGetValue(HPROFILE p,const char*s,const char*k,float*v,unsigned i){const char*x=ProfileInternal::IGetValue(p,s,k,i);if(!x||!v)return 0;*v=std::strtof(x,nullptr);return 1;}int ProfileGetValue(HPROFILE p,const char*s,const char*k,unreal*v,unsigned i){const char*x=ProfileInternal::IGetValue(p,s,k,i);if(!x||!v)return 0;*v=std::strtod(x,nullptr);return 1;}int ProfileGetValue(HPROFILE p,const char*s,const char*k,char*v,unsigned n,unsigned i){const char*x=ProfileInternal::IGetValue(p,s,k,i);if(!x||!v||!n)return 0;strncpy_s(v,n,x,_TRUNCATE);return 1;}
const char* ProfileGetValueNoCopy(HPROFILE p,const char*s,const char*k,unsigned i){return ProfileInternal::IGetValue(p,s,k,i);}unsigned ProfileGetNumValues(HPROFILE p,const char*s,const char*k){return ProfileInternal::IGetNumValues(p,s,k);}int ProfileGetValueIndex(HPROFILE p,const char*s,const char*k,const char*v){auto* value=ProfileInternal::GetKeyValue(p,s,k);if(!value||!v)return-1;for(unsigned i=0;i<value->values.size();++i)if(_stricmp(value->values[i].c_str(),v)==0)return static_cast<int>(i);return-1;}
void ProfileEnumKeys(HPROFILE p,const char*s,PROFILE_KEY_CALLBACK callback,void*user){if(!p||!s||!callback)return;auto it=p->sectionTable.find(s);if(it==p->sectionTable.end())return;for(const auto&[key,value]:it->second.keyTable)if(!callback(key.c_str(),value.values.empty()?"":value.values.front().c_str(),user))break;}void ProfileEnumSections(HPROFILE p,PROFILE_SECTION_CALLBACK callback,void*user){if(!p||!callback)return;for(const auto&[section,value]:p->sectionTable)if(!callback(section.c_str(),user))break;}int ProfileSectionExists(HPROFILE p,const char*s){return p&&s&&p->sectionTable.contains(s);}void ProfileClose(HPROFILE p){delete p;}
